<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigForceMfaAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigForceMfaAccessor trait.
 *
 * Covers null default, string/VO assignment via withForceMfa,
 * getForceMfa/forceMfa accessors, and isForceMfaChanged with/without original.
 */
class TenantConfigForceMfaAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withForceMfa creates a new instance with the ForceMfa set
     * from a string value, and getForceMfa returns the primitive string.
     */
    public function testWithForceMfaFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigForceMfaAccessorUnitTest();

        // Act
        $result = $holder->withForceMfa(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isForceMfa());
    }
    /**
     * Asserts that withforceMfa has access to the value object
     * from a string value, and getForceMfa returns the primitive string.
     */
    public function testWithForceMfaFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigForceMfaAccessorUnitTest();

        // Act
        $result = $holder->withForceMfa(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->forceMfa()->value());
    }
    public function testChangedForceMfa(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigForceMfaAccessorUnitTest()->withForceMfa(true);
        $original = $holder->withForceMfa( true);
        $same = $holder->withForceMfa( true);
        $modified = $holder->withForceMfa(false);

        // Act
        $withSame = $original->isForceMfaChanged( $same );
        $withDiferent = $original->isForceMfaChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigForceMfaAccessorUnitTest
{
  use TenantConfigForceMfaAccessor;
}
